import {makeGalleryStore,makeArtAutosaver,unpackArt,artworkTitle} from './gallery.mjs';
import {artSvg,downloadArt} from './art.mjs';
import {progressSummary} from './progress.mjs';
import {makeNarrator} from './narration.mjs';
import {audioClips} from './audio-catalog.mjs';
import {mountMiniGame} from './games.mjs';
import {activities,stories,freshState,loadState,saveState,addProfile,activeProfile,complete,label,recommend} from './model.mjs';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const storage={getItem:k=>window.localStorage.getItem(k),setItem:(k,v)=>window.localStorage.setItem(k,v),removeItem:k=>window.localStorage.removeItem(k)};
const galleryStore=makeGalleryStore(storage);let galleryLimit=6,galleryNeedsRefresh=false;
let state=loadState(storage), view='home', filter='All', modalCleanup=null, lastFocus=null, storageFailed=false, avatar='🐰';
const root=$('#app'), modalRoot=$('#modal-root');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tierName=l=>l==='preschool'?'Preschool':'Kindergarten';
function persist(){storageFailed=!saveState(storage,state);if(storageFailed)toast('Progress could not be saved. Browser storage may be full or blocked.');}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5000)}
const narrator=makeNarrator({attach:audio=>{audio.id="piko-audio";audio.hidden=true;document.body.append(audio)},clips:audioClips,enabled:()=>state.settings.sound,onPlaying:()=>{const note=$('#voice-note');if(note)note.hidden=true},onUnavailable:force=>{const note=$('#voice-note');if(note){note.textContent='Tap Listen to hear Piko’s guide.';note.hidden=false}if(force)toast('Audio could not play. Try Listen again, or download the offline version again.')}});
function say(text,force=false){return narrator.say(text,force)}
function stopSound(){narrator.stop()}
function modal(title,html,{wide=false,close=true}={}){if(modalCleanup){modalCleanup();modalCleanup=null}stopSound();clearTimeout(toast.timer);$('#toast').classList.remove('show');lastFocus=document.activeElement;modalRoot.innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${escape(title)}"><div class="modal-head"><h2>${escape(title)}</h2>${close?'<button class="close" aria-label="Close">×</button>':''}</div>${html}</section></div>`;document.body.style.overflow='hidden';root.inert=true;$('.close',modalRoot)?.addEventListener('click',closeModal);setTimeout(()=>($('input, .option, button, canvas',modalRoot)??$('.modal',modalRoot))?.focus(),40);modalRoot.dataset.dismiss=close?'yes':'no'}
function closeModal(){modalCleanup?.();modalCleanup=null;stopSound();modalRoot.innerHTML='';document.body.style.overflow='';root.inert=false;if(galleryNeedsRefresh&&view==='progress'){galleryNeedsRefresh=false;render();const heading=$('#gallery-title');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true})}else lastFocus?.isConnected&&lastFocus.focus();}
document.addEventListener('keydown',e=>{if(!modalRoot.firstChild)return;if(e.key==='Escape'&&modalRoot.dataset.dismiss==='yes'){closeModal();return}if(e.key==='Tab'){const els=$$('button:not(:disabled),input,select,a[href],canvas[tabindex]',modalRoot).filter(e=>!e.hidden);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||!modalRoot.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function logo(){return '<img src="icon.svg" alt=""><span>Taman Main<small>GROW THROUGH PLAY</small></span>'}
function card(a){const r=activeProfile(state)?.progress[a.id];return `<button class="activity-card" data-activity="${a.id}" aria-label="Play ${escape(a.title)}"><div class="activity-art ${a.color}"><span class="spark">✦</span><span class="big">${a.icon}</span><span class="doodle">${a.category==='Numbers'?'✦':a.category==='Creativity'?'〰':'✧'}</span></div><div class="activity-info"><div class="tag">${a.category}<span>${r?'✓ Explored':a.isNew?'✦ NEW':'2–3 minutes'}</span></div><h3>${a.title}</h3><p>${a.desc}</p><div class="activity-foot"><span>${r?label(r):'Tap, try, and discover'}</span><span class="play-dot">▶</span></div></div></button>`}
function header(){const p=activeProfile(state);return `<header class="header"><button class="brand" data-go="home" aria-label="Taman Main, home">${logo()}</button><nav class="nav" aria-label="Main navigation">${[['home','Home'],['games','Choose a Game'],['books','Storybooks'],['progress','My Adventures']].map(([id,t])=>`<button data-go="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${t}</button>`).join('')}</nav><div class="header-tools"><button class="round" id="sound" aria-label="${state.settings.sound?'Turn off':'Turn on'} sound" aria-pressed="${state.settings.sound}">${state.settings.sound?'♪':'♩'}</button><button class="parent-link" id="parents" aria-label="Grown-up area">♧ <span>Grown-ups</span></button><button class="profile-btn" id="profile" aria-label="Choose a child profile"><span class="avatar">${p?.avatar??'🐰'}</span><span class="profile-name">${escape(p?.name??'Child profile')}</span><span>⌄</span></button></div></header>`}
function home(){const p=activeProfile(state);const n=p?.name??'little friend';return `<div class="hello-row"><div><div class="greeting">Hello, ${escape(n)}! <span aria-hidden="true">☀️</span></div><button class="text-link adventure-home-link" data-go="progress">View my adventures ↗</button><p>A lovely day to discover something new.</p></div>${levels()}</div><section class="hero"><div class="hero-copy"><div class="eyebrow"><span>✿</span> WELCOME TO TAMAN MAIN</div><h1>A little play,<br>a little <em>growing.</em></h1><p>Little adventures, big discoveries.<br>Learn, explore, and smile with Piko!</p><button class="button" id="start">${state.session?.profile===state.active?'Continue adventure':'Let’s start playing'} <span>↗</span></button><span class="hero-meta">◷ &nbsp; 5–10 minutes · 3 activities</span></div><img class="hero-art" src="garden.svg" alt="Piko the bunny and Bubu the bear playing in a flower garden"></section><div class="feature-grid"><section class="feature-card"><div class="feature-icon">🗺️</div><div><span class="eyebrow" style="font-size:9px">TODAY’S ADVENTURE</span><h3>Little steps, big discoveries</h3><p>Three games picked for ${escape(n)}.</p><button class="text-link" id="journey">${state.session?.profile===state.active?'Continue':'View'} adventure &nbsp; →</button></div><div class="mini-path"><i>1</i><span>···</span><i>2</i><span>···</span><i>⚑</i></div></section><section class="feature-card"><div class="feature-icon" style="background:#f4e7d5">📚</div><div><span class="eyebrow" style="font-size:9px">STORY TIME</span><h3>One story, so much to discover</h3><p>Snuggle up, open a book, and imagine.</p><button class="text-link" data-go="books">Choose a storybook &nbsp; →</button></div></section></div><div class="section-head"><div><h2>What shall we play today?</h2><p>Follow your curiosity. There is so much to try.</p></div><button class="text-link" data-go="games">View all &nbsp; →</button></div>${filterChips()}<div class="activity-grid">${filteredActivities().slice(0,3).map(card).join('')}</div><section class="together"><span class="plant">🌿</span><div><h3>Learning is more fun together.</h3><p>Keep exploring after you play.<br>Can you find three round things at home?</p></div><button class="text-link" id="together">For grown-ups &nbsp; →</button></section>`}
function levels(){const l=activeProfile(state)?.level??'preschool';return `<div class="level-switch" aria-label="Learning level">${['preschool','kindergarten'].map(t=>`<button data-tier="${t}" class="${t===l?'active':''}" aria-pressed="${t===l}">${tierName(t)}</button>`).join('')}</div>`}
function filterChips(){return `<div class="filters" aria-label="Game categories">${[['All','✦'],['Language','Aa'],['Numbers','123'],['Thinking','◇'],['Creativity','〰'],['Feelings','♡']].map(([t,i])=>`<button class="chip ${filter===t?'active':''}" data-filter="${t}" aria-pressed="${filter===t}"><span>${i}</span>${t==='All'?'All games':t}</button>`).join('')}</div>`}
function filteredActivities(){return activities.filter(a=>a.level===(activeProfile(state)?.level??'preschool')&&(filter==='All'||a.category===filter)).sort((a,b)=>Number(!!b.isArt)-Number(!!a.isArt)||Number(!!b.isNew)-Number(!!a.isNew))}
function games(){return `<div class="hello-row"><div><span class="eyebrow">THE DISCOVERY GARDEN</span><h1 class="page-title">Choose your game</h1><p>Learn your way, one discovery at a time.</p></div>${levels()}</div>${filterChips()}<div class="activity-grid">${filteredActivities().map(card).join('')}</div><section class="together"><span class="plant">🐰</span><div><h3>Every try is something to celebrate.</h3><p>Still looking for the answer? Piko can help. Take your time.</p></div></section>`}
function books(){return `<span class="eyebrow">THE STORY CORNER</span><h1 class="page-title">Open a book. Open a world.</h1><p class="subline">Read together, listen, then tell the story your way.</p><div class="activity-grid">${stories.map(s=>`<button class="activity-card" data-story="${s.id}"><div class="activity-art ${s.color}" style="height:210px"><span class="spark">✦</span><span class="big" style="font-size:90px">${s.icon}</span><span class="doodle">✧</span></div><div class="activity-info"><div class="tag">PICTURE BOOK <span>4 pages</span></div><h3>${s.title}</h3><p>${s.subtitle}</p><div class="activity-foot"><span>${activeProfile(state)?.stories.includes(s.id)?'✓ Read together':'Read and listen'}</span><span class="play-dot">▶</span></div></div></button>`).join('')}</div><section class="together"><span class="plant">💬</span><div><h3>Pause for a little story chat.</h3><p>“What do you think happens next?” Little questions can start wonderful conversations.</p></div></section>`}
function createArtSession(activity,savedWork){
 const owner=activeProfile(state);const saved=savedWork?.profileId===owner.id?savedWork:null;let id=saved?.id??null,revision=saved?.revision??null;
 const session={initialState:saved?unpackArt(saved.data):null,onStatus:null,newArtwork(){id=null;revision=null}};
 const saver=makeArtAutosaver(art=>{const result=galleryStore.save(owner.id,activity.id,art,{id,revision});if(result.ok){id=result.item.id;revision=result.item.revision;galleryNeedsRefresh=true}return result},notice=>{session.onStatus?.(notice);if(notice.state==='error')toast('Your artwork has not been saved. Try saving again or download an SVG. Earlier artwork is safe.')});
 return Object.assign(session,saver);
}
function artworkImage(item){const art=unpackArt(item.data);return art?'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(artSvg(art)):''}
function gallerySection(){galleryNeedsRefresh=false;
 const p=activeProfile(state);if(!p)return '';const list=galleryStore.list(p.id),items=list.items;
 return `<section class="child-gallery" aria-labelledby="gallery-title"><div class="section-head"><div><span class="eyebrow">COLORS, LINES, AND IMAGINATION</span><h2 id="gallery-title">My Artwork</h2><p>Artwork by ${escape(p.name)}, from both learning levels.</p></div><button class="text-link" data-go="games" data-category="Creativity">Make new artwork →</button></div>${!list.ok?'<p class="gallery-warning" role="alert">Some artwork could not be loaded. Existing artwork is kept. Try reloading the page; keep your browser data.</p>':''}${items.length?`<div class="gallery-grid">${items.slice(0,galleryLimit).map(item=>{const a=activities.find(a=>a.id===item.activityId);return `<button class="gallery-card" data-artwork="${escape(item.id)}" aria-label="Open ${escape(artworkTitle(item))}, ${escape(a.title)}"><img src="${artworkImage(item)}" alt="Preview of ${escape(artworkTitle(item))}" loading="lazy" width="600" height="360"><span class="gallery-card-copy"><strong>${escape(artworkTitle(item))}</strong><span>${escape(a.title)}</span><small>${tierName(a.level)} · Open and continue ↗</small></span></button>`}).join('')}</div>${items.length>galleryLimit?'<button class="button light gallery-more" id="gallery-more">Show more artwork</button>':''}`:'<div class="gallery-empty"><span aria-hidden="true">🖍️</span><h3>Your little gallery is ready.</h3><p>Start drawing or coloring. Your artwork will be saved here for this profile.</p><button class="button light" data-go="games" data-category="Creativity">Let’s make something →</button></div>'}<p class="gallery-note">Saved in this browser on this device and available offline. Clearing browser data also removes artwork. Download an SVG for a backup.</p></section>`;
}
function openArtwork(id){
 const owner=activeProfile(state),item=owner?galleryStore.get(owner.id,id):null;if(!item){toast('This artwork could not be opened. Try reloading the gallery.');return}
 const activity=activities.find(a=>a.id===item.activityId),art=unpackArt(item.data);if(!activity||!art)return;
 modal(artworkTitle(item),`<p class="gallery-view-subtitle">${escape(activity.title)} · ${tierName(activity.level)} · By ${escape(owner.name)}</p><img class="gallery-large" src="${artworkImage(item)}" alt="${escape(artworkTitle(item))}"><p class="gallery-note">Continue this artwork to save changes to the same picture.</p><div class="modal-actions"><button class="button light" id="gallery-download">↓ Download SVG</button><button class="button" id="gallery-resume">Continue artwork →</button></div>`,{wide:true});
 $('#gallery-download').onclick=()=>downloadArt(art,'Taman-Main-'+artworkTitle(item).replaceAll(' ','-')+'.svg');
 $('#gallery-resume').onclick=()=>{if(activeProfile(state)?.id!==owner.id)return;const latest=galleryStore.get(owner.id,id);if(latest)playActivity(latest.activityId,false,latest);else toast('This artwork could not be opened. Try reloading the gallery.')};
}

function dashboard(){
 const d=progressSummary(state),p=d.profile;
 if(!p)return '<section class="empty"><h1 class="page-title" tabindex="-1">My Adventures</h1><p>Choose a child profile to see their learning garden.</p><button class="button" id="dashboard-profile">Choose a child profile</button></section>';
 const seen=d.finished+d.storyFinished>0;
 return `<section class="adventure-welcome"><div><span class="eyebrow">MY LEARNING GARDEN · ${tierName(p.level)}</span><h1 class="page-title" tabindex="-1">My Adventures</h1><p>Hello, ${escape(p.name)}! ${seen?'Look at everything you have explored.':'Your garden is ready to grow. Let’s try your first game.'}</p><button class="button" id="journey">${state.session?.profile===p.id?'Continue adventure':'Keep playing'} <span aria-hidden="true">→</span></button></div><div class="adventure-friend" aria-hidden="true"><span>${p.avatar}</span><small>Every little try<br>helps you grow.</small></div></section>
 <section class="adventure-tally" aria-label="Learning journey for ${escape(p.name)}"><div><span class="tally-icon" aria-hidden="true">🧩</span><p><strong>${d.finished}<small> / ${d.total}</small></strong><span>Games completed</span></p></div><div><span class="tally-icon" aria-hidden="true">📖</span><p><strong>${d.storyFinished}<small> / ${d.storyTotal}</small></strong><span>Stories read</span></p></div><div><span class="tally-icon" aria-hidden="true">🖍️</span><p><strong>${d.artFinished}<small> / ${d.artTotal}</small></strong><span>Art activities completed</span></p></div></section><p class="adventure-caption">Art activities are also included in completed games. Game progress follows the ${tierName(p.level)} level.</p>
 <section aria-labelledby="garden-progress-title"><div class="section-head"><div><h2 id="garden-progress-title">Watch my garden grow</h2><p>Tap a garden bed to choose a game.</p></div><span class="adventure-level">${tierName(p.level)}</span></div><div class="adventure-garden">${d.categories.map(c=>`<button class="progress-bed ${c.color}" data-go="games" data-category="${c.name}" aria-label="Open games in ${c.name}, ${c.finished} of ${c.total} completed"><div class="bed-illustration" aria-hidden="true"><span class="bed-symbol">${c.icon}</span><span class="bed-flower" style="--plant-size:${45+Math.round(c.finished/Math.max(1,c.total)*35)}px">${c.finished===0?'🌱':c.finished===c.total?'🌻':'🌼'}</span><span class="bed-soil"></span></div><h3>${c.name}</h3><span class="bed-count">${c.finished} of ${c.total} completed</span><div class="bed-progress" role="progressbar" aria-label="Progress in ${c.name}" aria-valuemin="0" aria-valuemax="${c.total}" aria-valuenow="${c.finished}"><span style="width:${c.finished/Math.max(1,c.total)*100}%"></span></div><span class="bed-action">Explore <span aria-hidden="true">↗</span></span></button>`).join('')}</div></section>
 ${gallerySection()}<section aria-labelledby="next-progress-title"><div class="section-head"><div><h2 id="next-progress-title">What would you like to explore next?</h2><p>${d.finished===d.total?'You have explored every game. Play your favorites again.':'Choose something you are curious about. You can play again any time.'}</p></div><button class="text-link" data-go="games">All games →</button></div><div class="activity-grid">${d.suggestions.map(card).join('')}</div></section>
 <section class="together"><span class="plant" aria-hidden="true">📚</span><div><h3>Stories are adventures too.</h3><p>${d.storyFinished===d.storyTotal?'You have read both stories together. Let’s read a favorite again.':'Sit with a grown-up and discover a new story.'}</p></div><button class="text-link" data-go="books">Open a storybook →</button></section>`;
}

function render(){root.innerHTML=`${storageFailed?'<div class="storage-error" role="alert">Device storage is unavailable. Progress will only last while this page stays open.</div>':''}${header()}<main class="main" id="main">${view==='home'?home():view==='games'?games():view==='books'?books():view==='progress'?dashboard():parents()}</main><footer class="footer"><div class="brand">${logo()}</div><div class="footer-note">Made for big imaginations.<br><button class="text-link" id="privacy" style="padding:5px 0;font-size:10px">No account · Progress on this device</button></div></footer>`;$('#main h1')?.setAttribute('tabindex','-1');$$('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go,b.dataset.category??'All'));$$('[data-activity]').forEach(b=>b.onclick=()=>playActivity(b.dataset.activity));$$('[data-story]').forEach(b=>b.onclick=()=>playStory(b.dataset.story));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$$('[data-tier]').forEach(b=>b.onclick=()=>{if(activeProfile(state)?.level===b.dataset.tier)return;gate(()=>changeLevel(b.dataset.tier))});$('#sound').onclick=()=>{state.settings.sound=!state.settings.sound;persist();stopSound();render();if(state.settings.sound)say('Hello, welcome to Taman Main!',true)};$('#parents').onclick=()=>gate(()=>navigate('parents'));$('#profile').onclick=chooseProfile;$('#start')?.addEventListener('click',startJourney);$('#journey')?.addEventListener('click',startJourney);$('#together')?.addEventListener('click',()=>gate(()=>navigate('parents')));$('#privacy').onclick=privacy;$('#dashboard-profile')?.addEventListener('click',chooseProfile);$$('[data-artwork]').forEach(b=>b.onclick=()=>openArtwork(b.dataset.artwork));$('#gallery-more')?.addEventListener('click',()=>{const count=galleryLimit;galleryLimit+=6;render();$$('[data-artwork]')[count]?.focus()});bindParents();}
function navigate(v,category='All'){closeModal();view=v;filter=category;render();window.scrollTo(0,0);$('#main h1')?.focus({preventScroll:true})}
function privacy(){modal('About Taman Main',`<p class="about-copy">Taman Main is an early learning space in English. Its illustrations and stories were made for this app.</p><p class="about-copy">Nicknames, settings, progress, and artwork are saved in this browser. There are no accounts, ads, or analytics trackers. Clearing browser data removes progress. Other devices and browsers keep separate progress.</p><p class="about-copy">Fonts load from Google Fonts when online; local fallback fonts are used offline. English narration is included in the app and saved with the offline download. No installed system voice is needed to play it.</p><p class="notice">These are early learning activities, rather than a developmental assessment or an educator-validated curriculum. Play together with a grown-up.</p>`)}
function profileForm(first=false){avatar='🐰';modal(first?'Welcome, little friend!':'Add a playmate',`<div class="onboarding">${first?'<div class="mascot">🐰 🌱</div><p class="subline">One little step toward a big discovery.<br>Let’s set up a profile with a grown-up.</p>':''}<form id="profile-form"><label class="field">Nickname<input name="name" maxlength="24" placeholder="For example: Alex" autocomplete="off"></label><label class="field">Learning level<select name="level"><option value="preschool">Preschool — discover and explore</option><option value="kindergarten">Kindergarten — connect and practice</option></select></label><div class="field">Choose your friend</div><div class="avatar-list">${['🐰','🐻','🐱','🐼','🦊','🐸'].map((a,i)=>`<button type="button" class="avatar-choice ${i===0?'active':''}" aria-label="Avatar ${['bunny','bear','cat','panda','fox','frog'][i]}" data-avatar="${a}">${a}</button>`).join('')}</div><p class="notice">No account needed. Progress stays on this device. Use a nickname; a full name is not needed.</p><button class="button" type="submit">${first?'Let’s enter the garden':'Save profile'} &nbsp; →</button></form></div>`,{close:!first});$$('[data-avatar]',modalRoot).forEach(b=>b.onclick=()=>{avatar=b.dataset.avatar;$$('[data-avatar]',modalRoot).forEach(el=>el.classList.toggle('active',el===b))});$('#profile-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);addProfile(state,String(f.get('name')),String(f.get('level')),avatar);persist();closeModal();view='home';render();say('Hi! I’m Piko. Let’s play and learn together.')}}
function chooseProfile(){if(!state.profiles.length)return profileForm(true);modal('Who is ready to play?',`${state.profiles.map(p=>`<button class="profile-row" data-select-profile="${p.id}"><span class="avatar">${p.avatar}</span><span><strong>${escape(p.name)}</strong><small>${tierName(p.level)}</small></span>${p.id===state.active?'✓':'→'}</button>`).join('')}<button class="button light" id="add-profile">＋ Add a profile with a grown-up</button>`);$$('[data-select-profile]',modalRoot).forEach(b=>b.onclick=()=>{state.active=b.dataset.selectProfile;galleryLimit=6;state.session=null;persist();navigate('home')});$('#add-profile').onclick=()=>gate(()=>profileForm())}
function gate(after){const a=4+Math.floor(Math.random()*5),b=3+Math.floor(Math.random()*6);modal('A moment for grown-ups',`<p>This area is for grown-ups. Solve this addition problem to continue.</p><div class="gate-problem">${a} + ${b} = ?</div><form id="gate-form"><label class="field">Answer<input name="answer" inputmode="numeric" pattern="[0-9]+" required autocomplete="off" aria-describedby="gate-error"></label><p id="gate-error" role="status" class="gate-label"></p><div class="modal-actions"><button class="button" type="submit">Continue →</button></div></form>`);$('#gate-form').onsubmit=e=>{e.preventDefault();if(Number(new FormData(e.target).get('answer'))!==a+b){$('#gate-error').textContent='That answer is not quite right. Please try again.';return}closeModal();after()}}
function changeLevel(t){const p=activeProfile(state);if(!p)return;p.level=t;state.session=null;persist();closeModal();filter='All';render();toast(`Learning level for ${escape(p.name)} changed to ${tierName(t)}. Earlier progress is kept.`)}
function startJourney(){const p=activeProfile(state);if(!p)return profileForm(true);if(!state.session||state.session.profile!==p.id){state.session={profile:p.id,ids:recommend(state).map(a=>a.id),index:0,started:Date.now(),done:false};persist()}playActivity(state.session.ids[state.session.index],true)}
function playActivity(id,journey=false,savedWork=null){const a=activities.find(x=>x.id===id);if(!a||!activeProfile(state))return;let attempts=1,won=false,usedHint=false;const session=journey?state.session:null;if(session?.done)return showSuccess(a,true);modal(a.title,`<div class="play-top"><span>${journey?`Activity ${session.index+1} of 3`:tierName(a.level)}</span><div class="progressbar"><span style="width:${journey?session.index/3*100:0}%"></span></div><span>${a.category}</span></div><h3 class="activity-title">${a.prompt}</h3><button class="listen" id="listen">♪ Listen again</button><p class="voice-note" id="voice-note" role="status" hidden></p>${a.kind==='mini'?'<div id="mini-container"></div>':a.kind==='trace'?'<div class="trace-wrap"><canvas id="trace" width="600" height="260" tabindex="0" aria-label="Tracing area. Use a finger or mouse. With a keyboard, press Enter to start, then use the arrow keys to trace."></canvas></div><div class="trace-tools"><button class="chip" id="clear-trace">↺ Try tracing again</button><span id="trace-score">Follow the path from the green dot.</span><button class="button small" id="check-trace">Finish drawing ✓</button></div>':a.kind==='order'?'<div class="order-slots"><div class="order-slot">1</div><div class="order-slot">2</div><div class="order-slot">3</div></div>':`<div class="visual" aria-label="${escape(a.visual)}">${a.visual}</div>`}${!['trace','mini'].includes(a.kind)?`<div class="options">${a.options.map((v,i)=>`<button class="option ${v.length>5?'long':''}" data-option="${i}">${v}</button>`).join('')}</div>`:''}<div class="feedback" role="status" aria-live="polite"></div><button class="hint" id="hint">☀ Need a hint?</button><p class="duration-note">Take your time. Every try helps you learn.</p>`,{wide:true});$('#listen').onclick=()=>say(a.prompt,true);$('#hint').onclick=()=>{usedHint=true;$('.feedback').textContent=a.hint;say(a.hint)};if(a.kind!=='mini')say(a.prompt);
 const success=()=>{if(won)return;won=true;complete(state,id,usedHint?Math.max(2,attempts):attempts);if(session)session.done=true;persist();$$('.option').forEach(b=>b.disabled=true);$('.feedback').innerHTML='Great exploring! You gave it a try! <br><button class="button small" id="activity-next" style="margin-top:12px">Continue →</button>';$('#hint').hidden=true;$('#activity-next').onclick=()=>showSuccess(a,journey);const next=$('#activity-next');if(a.kind!=='mini'){next.disabled=true;say('Great exploring! You gave it a try!').then(()=>{if(next.isConnected){next.disabled=false;next.focus()}})}render();if(!next.disabled)next.focus();};
 if(a.kind==='choice')$$('[data-option]',modalRoot).forEach(b=>b.onclick=()=>{if(won)return;const correct=a.options[Number(b.dataset.option)]===a.answer;if(correct){b.classList.add('correct');success()}else{attempts++;b.classList.add('wrong');$('.feedback').textContent='Not quite yet. Take a look and try again.';say('Let’s try again.');setTimeout(()=>b.classList.remove('wrong'),600)}});
 if(a.kind==='order'){let selected=[];$$('[data-option]',modalRoot).forEach(b=>b.onclick=()=>{if(won)return;const v=a.options[Number(b.dataset.option)];if(v!==a.answer[selected.length]){attempts++;$('.feedback').textContent=a.hint;say(a.hint);return}selected.push(v);b.disabled=true;$$('.order-slot')[selected.length-1].textContent=v;if(selected.length===3)success()})}
 if(a.kind==='mini'){modalCleanup=mountMiniGame({activity:a,container:$('#mini-container'),onSuccess:success,onMistake:()=>{attempts++},speak:say,soundEnabled:()=>state.settings.sound,artSession:a.isArt?createArtSession(a,savedWork):null});$('#hint').hidden=true;$('#listen').onclick=()=>modalCleanup?.replay?.();}
 if(a.kind==='trace')setupTrace(a,()=>{success()},()=>{attempts++;$('.feedback').textContent='Try following more of the dotted line, starting at the green dot.'});
}
function setupTrace(a,success,failed){const canvas=$('#trace'),ctx=canvas.getContext('2d');let points=[],drawing=false,keyboard=false,cursor={x:a.shape==='one'?300:65,y:a.shape==='one'?42:130};const target=a.shape==='one'?[[300,42],[300,220]]:[[65,130],[535,130]];const bins=new Set();let near=0;function draw(){ctx.clearRect(0,0,600,260);ctx.lineWidth=20;ctx.strokeStyle='#f0efe4';ctx.lineCap='round';ctx.beginPath();ctx.moveTo(...target[0]);ctx.lineTo(...target[1]);ctx.stroke();ctx.lineWidth=3;ctx.setLineDash([7,12]);ctx.strokeStyle='#a1ae8e';ctx.beginPath();ctx.moveTo(...target[0]);ctx.lineTo(...target[1]);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#799e68';ctx.beginPath();ctx.arc(...target[0],13,0,7);ctx.fill();ctx.font='28px sans-serif';ctx.fillText(a.shape==='one'?'⭐':'🌼',target[1][0]-15,target[1][1]+12);ctx.strokeStyle='#75a494';ctx.lineWidth=12;for(let i=1;i<points.length;i++){if(points[i].start)continue;ctx.beginPath();ctx.moveTo(points[i-1].x,points[i-1].y);ctx.lineTo(points[i].x,points[i].y);ctx.stroke()}if(keyboard){ctx.strokeStyle='#365f49';ctx.lineWidth=3;ctx.beginPath();ctx.arc(cursor.x,cursor.y,9,0,7);ctx.stroke()}}
 function add(p,start=false){points.push({...p,start});const t=a.shape==='one'?(p.y-42)/178:(p.x-65)/470;const distance=a.shape==='one'?Math.abs(p.x-300):Math.abs(p.y-130);if(t>=0&&t<=1&&distance<28){near++;bins.add(Math.min(13,Math.floor(t*14)))}draw();$('#trace-score').textContent=`Path traced: ${Math.round(bins.size/14*100)}%`}
 const pos=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*600/r.width,y:(e.clientY-r.top)*260/r.height}};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);add(pos(e),true)};canvas.onpointermove=e=>{if(drawing)add(pos(e))};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;canvas.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();keyboard=!keyboard;if(keyboard)add(cursor,true);draw()}if(e.key.startsWith('Arrow')){e.preventDefault();if(!keyboard){keyboard=true;add(cursor,true)}cursor.x=Math.max(0,Math.min(600,cursor.x+(e.key==='ArrowRight'?12:e.key==='ArrowLeft'?-12:0)));cursor.y=Math.max(0,Math.min(260,cursor.y+(e.key==='ArrowDown'?8:e.key==='ArrowUp'?-8:0)));add(cursor)}};$('#clear-trace').onclick=()=>{points=[];bins.clear();near=0;draw();$('#trace-score').textContent='Follow the path from the green dot.'};$('#check-trace').onclick=()=>{if(bins.size>=10&&near/Math.max(1,points.length)>=.65){$('#check-trace').disabled=true;success()}else failed()};draw();modalCleanup=()=>{canvas.onpointerdown=canvas.onpointermove=canvas.onkeydown=null}}
function showSuccess(a,journey){modal('A new discovery!',`<div class="celebrate"><span class="medal">🌟</span><span class="eyebrow">THANK YOU FOR EXPLORING</span><h2>You did it!</h2><p>${a.title} is explored.<br>Every try helps you learn.</p><div class="home-task"><h3>🌿 Try this at home</h3><p>${a.home}</p></div><div class="modal-actions"><button class="button" id="finish-step">${journey&&state.session.index<2?'Next game →':journey?'Finish adventure →':'Back to the garden →'}</button></div></div>`);$('#finish-step').onclick=()=>{if(journey&&state.session){state.session.index++;state.session.done=false;if(state.session.index<3){persist();playActivity(state.session.ids[state.session.index],true);return}const elapsed=Date.now()-state.session.started;state.session=null;persist();render();modal('Adventure complete!',`<div class="celebrate"><span class="medal">🏕️</span><h2>Three little steps.<br>So many new discoveries!</h2><p>${elapsed>=state.settings.duration*60000?'You have had a lovely time playing.':'Now it is time for a little break.'} Let’s move around and play with a grown-up.</p><div class="home-task"><h3>A real-world adventure</h3><p>${a.home}</p></div><div class="modal-actions"><button class="button" id="back-garden">Back to the garden →</button></div></div>`);$('#back-garden').onclick=()=>navigate('home');return}navigate('home')}}
function playStory(id,page=0){const s=stories.find(x=>x.id===id);if(!s||!activeProfile(state))return;const [icon,text]=s.pages[page];modal(s.title,`<div class="play-top"><span>Page ${page+1} of ${s.pages.length}</span><div class="progressbar"><span style="width:${(page+1)/s.pages.length*100}%"></span></div></div><div class="story-art ${s.color}" style="margin-top:18px">${icon}</div><p class="story-text">${text}</p><button class="listen" id="story-listen">♪ Listen to the story</button><div class="modal-actions"><button class="button light" id="story-prev" ${page===0?'disabled':''}>← Previous</button><button class="button" id="story-next">${page<s.pages.length-1?'Next →':'Finish reading ✓'}</button></div>`,{wide:true});$('#story-prev').onclick=()=>playStory(id,page-1);$('#story-listen').onclick=()=>say(text,true);$('#story-next').onclick=()=>{if(page<s.pages.length-1)return playStory(id,page+1);const p=activeProfile(state);if(!p.stories.includes(id))p.stories.push(id);persist();render();modal('Let’s talk about the story',`<div class="celebrate"><span class="medal">💬</span><h2>What do you think?</h2><p>${s.question}</p><div class="home-task"><h3>Keep exploring with a grown-up</h3><p>${s.home}</p></div><div class="modal-actions"><button class="button" id="story-end">Back to storybooks →</button></div></div>`);$('#story-end').onclick=()=>navigate('books')};say(text)}
function parents(){const p=activeProfile(state);return `<div class="parent-header"><div><span class="eyebrow">GROWING TOGETHER</span><h1 class="page-title">Grown-up corner</h1><p class="subline">Discover the little steps taken by ${escape(p?.name??'your child')} today.</p></div><button class="button light" data-go="home">← Back to play</button></div><div class="parent-grid"><section class="panel"><h3>🌱 Learning journey for ${escape(p?.name??'your child')}</h3><p class="subline">${tierName(p?.level)} · ${Object.keys(p?.progress??{}).length} activities explored</p>${activities.filter(a=>a.level===p?.level).map(a=>{const r=p.progress[a.id];return `<div class="progress-row"><span class="emoji">${a.icon}</span><div>${a.title}<small>${r?`${r.runs} ${r.runs===1?'try':'tries'}`:'Not explored yet'}</small></div><span class="badge">${r?label(r):'Not explored yet'}</span></div>`}).join('')}<p class="notice">“Growing confident” means completing an activity twice in a row without a wrong answer or a hint. This is not a developmental assessment.</p></section><div><section class="panel"><h3>Family settings</h3><label class="settings-row">Learning level<select id="setting-level"><option value="preschool" ${p?.level==='preschool'?'selected':''}>Preschool</option><option value="kindergarten" ${p?.level==='kindergarten'?'selected':''}>Kindergarten</option></select></label><label class="settings-row">Voice guidance<input type="checkbox" id="setting-sound" ${state.settings.sound?'checked':''}></label><label class="settings-row">Break reminder<select id="setting-duration">${[5,10,15].map(n=>`<option value="${n}" ${state.settings.duration===n?'selected':''}>${n} minutes</option>`).join('')}</select></label><p class="notice">The reminder appears after an adventure without interrupting a game. Piko’s English recordings are included in the app. Tap Listen again to replay a guide.</p><button class="button light small" id="manage-profiles">Manage child profiles</button></section><section class="panel" style="margin-top:20px"><h3>Play offline</h3><p class="subline">Save games and stories on this device. When the download finishes, open the same web address to play without the internet.</p><button class="button small" id="download">↓ Download for offline</button><p id="offline-status" class="offline-pill" role="status">Checking download…</p><p class="notice">Piko’s guides and story recordings are included in the download. No installed system voice is needed.</p></section><section class="panel" style="margin-top:20px"><h3>Data on this device</h3><p class="subline">No account. Data does not sync to other devices. Clearing browser data also removes progress and artwork.</p><button class="danger" id="delete-profile">Delete profile ${escape(p?.name??'your child')}, progress, and artwork</button></section></div></div>`}
function bindParents(){if(view!=='parents')return;$('#setting-level').onchange=e=>changeLevel(e.target.value);$('#setting-sound').onchange=e=>{state.settings.sound=e.target.checked;persist();if(!e.target.checked)stopSound()};$('#setting-duration').onchange=e=>{state.settings.duration=Number(e.target.value);persist()};$('#manage-profiles').onclick=chooseProfile;$('#download').onclick=downloadOffline;offlineStatus();$('#delete-profile').onclick=()=>{const p=activeProfile(state);modal('Delete this profile?',`<p>Profile <strong>${escape(p.name)}</strong> and its progress, story history, and all gallery artwork will be deleted from this browser. This cannot be undone.</p><div class="modal-actions"><button class="button light" id="cancel-delete">Cancel</button><button class="danger" id="confirm-delete">Yes, delete this profile</button></div>`);$('#cancel-delete').onclick=closeModal;$('#confirm-delete').onclick=()=>{if(!galleryStore.removeProfile(p.id).ok){toast('The profile was not deleted because artwork storage is unavailable. Please try again.');return}state.profiles=state.profiles.filter(x=>x.id!==p.id);state.active=state.profiles[0]?.id??null;state.session=null;persist();navigate('home');if(!state.profiles.length)profileForm(true)}}}
async function offlineStatus(){
 const el=$('#offline-status');if(!el)return;
 if(location.protocol==='file:'){el.textContent='This single-file version already includes the games and stories. No extra download is needed.';$('#download').hidden=true;return}
 try{let ready=false,older=false;if('caches' in window){
  for(const name of await caches.keys())if(name==='taman-main-v1'||name.startsWith('taman-main-download-')){
   const marker=await (await caches.open(name)).match('./__offline-ready');
   if(marker&&(await marker.text())==='ready:en-v1')ready=true;else older=true;
  }
 }
 el.textContent=ready?'✓ English games, stories, and audio are saved on this device.':older?'English update needed. Download again for offline.':'Not downloaded for offline yet.';
 }catch{el.textContent='Offline storage is unavailable in this browser.'}
}

let registration=null;
async function downloadOffline(){const b=$('#download');b.disabled=true;b.textContent='Saving games…';try{if(!('serviceWorker' in navigator))throw Error('unsupported');registration=await navigator.serviceWorker.register('./sw.js');const worker=registration.installing??registration.waiting??registration.active;if(!worker)throw Error('no-worker');if(worker.state!=='activated')await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('activation-timeout')),20000);const check=()=>{if(worker.state==='activated'){clearTimeout(timer);worker.removeEventListener('statechange',check);resolve()}else if(worker.state==='redundant'){clearTimeout(timer);worker.removeEventListener('statechange',check);reject(Error('activation-failed'))}};worker.addEventListener('statechange',check);check()});await new Promise((resolve,reject)=>{const ch=new MessageChannel();const timer=setTimeout(()=>reject(Error('timeout')),120000);ch.port1.onmessage=e=>{clearTimeout(timer);e.data.ok?resolve():reject(Error('cache'))};worker.postMessage({type:'DOWNLOAD'},[ch.port2])});toast('Games and stories are ready to play without the internet.');await offlineStatus()}catch{toast('The download did not finish. Check your internet connection and available browser storage.')}finally{b.disabled=false;b.textContent='↓ Download again for offline'}}

render();if(!state.profiles.length)profileForm(true);
window.addEventListener('online',()=>toast('You are back online.'));
window.addEventListener('offline',()=>toast('You are offline. Downloaded games are still ready to play.'));

window.addEventListener('pagehide',()=>{modalCleanup?.flush?.();stopSound()});
